import { createContext, useContext, useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { Link, NavLink, Navigate, Outlet, Route, Routes, useLocation, useNavigate } from 'react-router-dom';
import { Area, AreaChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { ArrowRight, BarChart3, Bell, BookOpen, Bot, Check, ChevronRight, CircleHelp, Code2, Compass, FileText, Flame, GraduationCap, LayoutDashboard, Loader2, LogOut, Menu, MessageCircle, Play, Plus, Route as RouteIcon, Search, Send, Settings, ShieldCheck, Sparkles, Target, Timer, TrendingUp, Trophy, UserRound, Users, X, Zap } from 'lucide-react';

const API = '/api';

async function api<T>(path: string, options: RequestInit = {}): Promise<T> {
  const token = localStorage.getItem('careerai_token');
  const headers = new Headers(options.headers);
  headers.set('Content-Type', 'application/json');
  if (token) headers.set('Authorization', `Bearer ${token}`);
  const response = await fetch(`${API}${path}`, { ...options, headers });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.detail || 'Something went wrong. Please try again.');
  return data as T;
}

interface User { id: number; name: string; email: string; role: string }
interface Profile { name: string; email: string; college: string; degree: string; branch: string; graduation_year: number; preferred_role: string; experience_level: string; career_goal: string; skills: string[]; resume_text: string }
interface Dashboard { overall_score: number; skills_completed: number; skill_gaps: number; aptitude_score: number; coding_progress: number; coding_score: number; interview_score: number; roadmap_progress: number; recommended_next_action: string; trend: { label: string; value: number }[]; recent_activity: { action: string; detail: string; created_at: string }[] }
interface Roadmap { id: number; title: string; role: string; progress: number; items: { id: number; week: number; title: string; description: string; completed: boolean }[] }
interface Gap { role: { name: string; description: string }; current: { name: string; priority: string; category: string }[]; missing: { name: string; priority: string; category: string }[]; progress: number; total: number }

interface AuthValue { user: User | null; loading: boolean; login: (email: string, password: string) => Promise<void>; register: (name: string, email: string, password: string) => Promise<void>; logout: () => void }
const AuthContext = createContext<AuthValue | null>(null);
function useAuth() { const value = useContext(AuthContext); if (!value) throw new Error('AuthContext missing'); return value; }

function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  useEffect(() => { const token = localStorage.getItem('careerai_token'); if (!token) { setLoading(false); return; } api<User>('/auth/me').then(setUser).catch(() => localStorage.removeItem('careerai_token')).finally(() => setLoading(false)); }, []);
  const login = async (email: string, password: string) => { const data = await api<{ token: string; user: User }>('/auth/login', { method: 'POST', body: JSON.stringify({ email, password }) }); localStorage.setItem('careerai_token', data.token); setUser(data.user); };
  const register = async (name: string, email: string, password: string) => { const data = await api<{ token: string; user: User }>('/auth/register', { method: 'POST', body: JSON.stringify({ name, email, password }) }); localStorage.setItem('careerai_token', data.token); setUser(data.user); };
  const logout = () => { localStorage.removeItem('careerai_token'); setUser(null); };
  return <AuthContext.Provider value={{ user, loading, login, register, logout }}>{children}</AuthContext.Provider>;
}

function Logo({ compact = false }: { compact?: boolean }) { return <Link to="/" className="brand"><span className="brand-mark"><span /></span>{!compact && <span>Career<span className="brand-accent">AI</span></span>}</Link>; }
function Button({ children, variant = 'primary', className = '', type = 'button', onClick, disabled = false }: { children: ReactNode; variant?: 'primary' | 'secondary' | 'ghost' | 'dark'; className?: string; type?: 'button' | 'submit'; onClick?: () => void; disabled?: boolean }) { return <button type={type} className={`btn btn-${variant} ${className}`} onClick={onClick} disabled={disabled}>{children}</button>; }
function Spinner() { return <Loader2 className="spin" size={18} />; }
function Badge({ children, tone = 'indigo' }: { children: ReactNode; tone?: 'indigo' | 'mint' | 'amber' | 'slate' }) { return <span className={`badge badge-${tone}`}>{children}</span>; }
function StatCard({ icon, label, value, detail, tone = 'indigo' }: { icon: ReactNode; label: string; value: string | number; detail: string; tone?: string }) { return <div className={`stat-card tone-${tone}`}><div className="stat-icon">{icon}</div><div><p>{label}</p><strong>{value}</strong><small>{detail}</small></div></div>; }
function ProgressRing({ value, size = 90 }: { value: number; size?: number }) { const radius = (size - 12) / 2; const circumference = 2 * Math.PI * radius; return <div className="progress-ring" style={{ width: size, height: size }}><svg width={size} height={size}><circle className="ring-track" cx={size / 2} cy={size / 2} r={radius} /><circle className="ring-value" cx={size / 2} cy={size / 2} r={radius} strokeDasharray={circumference} strokeDashoffset={circumference - (circumference * Math.min(value, 100)) / 100} /></svg><span>{value}%</span></div>; }
function EmptyState({ icon, title, body, action }: { icon: ReactNode; title: string; body: string; action?: ReactNode }) { return <div className="empty-state"><div className="empty-icon">{icon}</div><h3>{title}</h3><p>{body}</p>{action}</div>; }
function Toast({ message, onClose }: { message: string; onClose: () => void }) { return <div className="toast"><Check size={16} /> {message}<button onClick={onClose}><X size={15} /></button></div>; }

