    <section className="cta-band page-width"><div><div className="eyebrow">Your advantage is consistency</div><h2>Make the next week count.</h2><p>Build a plan you can actually keep.</p></div><Link to={user ? '/app' : '/register'} className="btn btn-dark btn-large">Start building <ArrowRight size={18} /></Link></section>
