function Feature({ icon, number, title, body }: { icon: ReactNode; number: string; title: string; body: string }) { return <div className="feature-card"><div className="feature-icon">{icon}</div><span className="feature-num">{number}</span><h3>{title}</h3><p>{body}</p><ArrowRight className="feature-arrow" size={17} /></div>; }
function Step({ num, title, body }: { num: string; title: string; body: string }) { return <div className="step"><span>{num}</span><div><h3>{title}</h3><p>{body}</p></div></div>; }
function Module({ icon, title, text }: { icon: ReactNode; title: string; text: string }) { return <div className="module-card"><div className="module-icon">{icon}</div><h3>{title}</h3><p>{text}</p><ChevronRight size={18} /></div>; }

function AuthPage({ mode }: { mode: 'login' | 'register' }) {
  const { user, login, register } = useAuth(); const navigate = useNavigate(); const [name, setName] = useState(''); const [email, setEmail] = useState(mode === 'login' ? 'demo@careerai.app' : ''); const [password, setPassword] = useState(mode === 'login' ? 'demo123' : ''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  if (user) return <Navigate to="/app" replace />;
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setError(''); try { if (mode === 'login') await login(email, password); else await register(name, email, password); navigate('/app'); } catch (err) { setError(err instanceof Error ? err.message : 'Unable to continue'); } finally { setBusy(false); } };
  return <div className="auth-page"><div className="auth-visual"><Logo /><div className="auth-visual-copy"><div className="eyebrow">The calmer path to placement</div><h1>Progress is a practice, not a personality trait.</h1><p>See what matters, work the plan, and let the evidence speak for you.</p></div><div className="auth-quote"><Sparkles size={17} /><span>“The first time my prep felt like a system.”<small>— Ananya, final-year CS student</small></span></div></div><div className="auth-panel"><Link to="/" className="back-link">← Back to home</Link><div className="auth-form"><div className="eyebrow">{mode === 'login' ? 'Welcome back' : 'Start with clarity'}</div><h2>{mode === 'login' ? 'Pick up where you left off.' : 'Create your career workspace.'}</h2><p className="form-subtitle">{mode === 'login' ? 'Your roadmap is waiting.' : 'Free to use. Built to help you move.'}</p>{error && <div className="alert alert-error">{error}</div>}<form onSubmit={submit}>{mode === 'register' && <label>Full name<input value={name} onChange={e => setName(e.target.value)} placeholder="Aarav Mehta" required /></label>}<label>Email address<input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="you@college.edu" required /></label><label>Password<input type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="At least 6 characters" required minLength={6} /></label><Button type="submit" className="btn-block" disabled={busy}>{busy ? <Spinner /> : mode === 'login' ? <>Log in <ArrowRight size={17} /></> : <>Create workspace <ArrowRight size={17} /></>}</Button></form>{mode === 'login' && <button className="demo-hint" onClick={() => { setEmail('demo@careerai.app'); setPassword('demo123'); }}>Use demo account · demo@careerai.app</button>}<p className="switch-auth">{mode === 'login' ? 'New here?' : 'Already have an account?'} <Link to={mode === 'login' ? '/register' : '/login'}>{mode === 'login' ? 'Create a workspace' : 'Log in'}</Link></p></div></div></div>;
}

